<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Builder; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class EjercicioRutina extends Model { protected $table='ejercicios_rutina'; protected $fillable=['sesion_rutina_id','ejercicio_id','orden','series','repeticiones_min','repeticiones_max','duracion_segundos','distancia','peso','descanso_segundos','rpe','rir','tempo','indicaciones']; protected function casts(): array { return ['orden'=>'integer','series'=>'integer','repeticiones_min'=>'integer','repeticiones_max'=>'integer','duracion_segundos'=>'integer','distancia'=>'decimal:2','peso'=>'decimal:2','descanso_segundos'=>'integer','rpe'=>'decimal:1','rir'=>'integer']; } public function scopeOrdenados(Builder $query): Builder { return $query->orderBy('orden'); } public function sesion(): BelongsTo { return $this->belongsTo(SesionRutina::class,'sesion_rutina_id'); } public function ejercicio(): BelongsTo { return $this->belongsTo(Ejercicio::class); } public function seriesRealizadas(): HasMany { return $this->hasMany(SerieRealizada::class); } public function rangoRepeticiones(): ?string { if($this->repeticiones_min===null)return null; return $this->repeticiones_max && $this->repeticiones_max!==$this->repeticiones_min ? "{$this->repeticiones_min}-{$this->repeticiones_max}" : (string)$this->repeticiones_min; } }
